import{_ as o,l as A,o as e,c as d,v as r,p as s,x as t,d as i,i as n,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"DAC / MAC / RBAC","description":"","frontmatter":{"title":"DAC / MAC / RBAC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dac-mac-rbac.md","filePath":"cs/dac-mac-rbac.md","lastUpdated":1789023840000}'),C={name:"cs/dac-mac-rbac.md"};function p(h,a,B,m,_,u){const l=A("Mermaid");return e(),d("div",null,[a[1]||(a[1]=r('<h1 id="dac-mac-rbac" tabindex="-1">DAC / MAC / RBAC <a class="header-anchor" href="#dac-mac-rbac" aria-label="Permalink to &quot;DAC / MAC / RBAC&quot;">​</a></h1><div class="epigraph"><p>自主访问控制让属主改 ACL；强制访问控制用标签策略挡住「自愿泄露」；角色把权限聚成岗位而不是每人一条。</p><footer>—— 据 Lampson 保护矩阵；Bell–LaPadula 对照；Sandhu 对 RBAC；Saltzer and Schroeder</footer></div><p><a href="/cs/acl-least-priv">上一课</a>给出主体–客体–操作与最小特权。本课不重画矩阵。缺口是政策谁来写：属主（DAC）、系统标签（MAC）、岗位角色（RBAC）。能力下一课对照矩阵的另一种存放。三者都能表达同一矩阵的子集，失败模式不同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最小特权课留下矩阵。Unix 文件 mode 是 DAC：属主可 chmod 把读权给别人，木马也能借属主去改。MAC：级别与范畴，写不上读下一类规则（教学用 BLP 直觉），用户不能自愿改标签以泄密。RBAC：权限授给角色，人授角色，便于岗位变动。缺口是<strong>三种政策来源</strong>。</p><p><span class="marginnote">MLS 的形式模型有争议与例外。主干只取「策略不由文件属主随意改」这一层。RBAC 可叠在 DAC 上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现：DAC 用 ACL 或 mode；MAC 用标签 + 引用监视器；RBAC 用角色表。检查总在引用监视器，与<a href="/cs/kernel-user">内核与用户态</a> 一致。本课不把 SELinux 类型列表当必背。</p>',8)),(e(),s(c,null,{default:t(()=>[n(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAT%5B%22%E4%BF%9D%E6%8A%A4%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20DAC%5B%22%E5%B1%9E%E4%B8%BB%E6%94%B9%20ACL%22%5D%0A%20%20MAT%20--%3E%20MAC%5B%22%E7%B3%BB%E7%BB%9F%E6%A0%87%E7%AD%BE%E7%AD%96%E7%95%A5%22%5D%0A%20%20MAT%20--%3E%20RBAC%5B%22%E8%A7%92%E8%89%B2%E8%81%9A%E5%90%88%E6%9D%83%E9%99%90%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DAC 灵活、难防内部误授。MAC 服务机密性轴的强政策，可用性与兼容性代价高。RBAC 降的是管理复杂度，不是新的形式保证。后课能力把「行」发给主体当票。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入基于属性的 ABAC 全貌当主干。矩阵按行发放不可伪造引用，下一课能力对 ACL。</p><p>后课默认：政策可来自属主、标签或角色。票与名单是两种表示。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DAC 属主做主；MAC 标签强制；RBAC 按岗位聚合。</li><li>引用监视器执行，不靠自愿遵守。</li><li>能力对照下一课。</li><li>出处：Lampson；Bell–LaPadula 对照；Sandhu RBAC；Saltzer and Schroeder。</li></ul>',7))])}const f=o(C,[["render",p]]);export{D as __pageData,f as default};
